//! The schema has to be the Python schema, exactly.
//!
//! The desktop's snapshot has to open on the phone, so the schema cannot
//! drift. There are two oracles here, and they are independent:
//!
//! 1. `the_schema_matches_the_python_models` reads `backend/app/models.py` and
//!    `backend/app/models_phase2.py` **at test time** and works out what the
//!    schema has to be.
//! 2. `the_schema_matches_the_golden_sqlalchemy_snapshot` compares against
//!    `tests/python_schema.json` — the store's golden fixture — which was
//!    generated by SQLAlchemy itself (`tests/generate_python_schema.py`).
//!    It is a checked-in expected output, compared exactly, like every other
//!    golden file in this project.
//!
//! A bug in the parser cannot hide a drift on its own, because the second
//! oracle does not use the parser.

// An integration test is its own crate, so clippy's allow-in-tests
// configuration does not cover it: the test code opts out here.
#![allow(clippy::unwrap_used, clippy::expect_used, clippy::panic)]

mod common;

use std::collections::BTreeMap;
use std::path::{Path, PathBuf};

use stride_store::{Store, StoreError};

// ---------------------------------------------------------------- the oracle

/// One column.
#[derive(Debug, Clone, PartialEq, Eq, PartialOrd, Ord)]
struct Column {
    name: String,
    ty: String,
    notnull: bool,
    default: Option<String>,
    primary_key: bool,
}

/// One index.
#[derive(Debug, Clone, PartialEq, Eq, PartialOrd, Ord)]
struct Index {
    name: String,
    unique: bool,
    columns: Vec<String>,
}

/// One foreign key.
#[derive(Debug, Clone, PartialEq, Eq, PartialOrd, Ord)]
struct ForeignKey {
    column: String,
    references_table: String,
    references_column: String,
    on_delete: String,
}

/// One table.
#[derive(Debug, Clone, PartialEq, Eq, PartialOrd, Ord)]
struct Table {
    name: String,
    columns: Vec<Column>,
    unique_constraints: Vec<Vec<String>>,
    indexes: Vec<Index>,
    foreign_keys: Vec<ForeignKey>,
}

/// The repository root, from this crate.
fn repo_root() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("..")
        .join("..")
        .canonicalize()
        .expect("could not find the repository root")
}

// ------------------------------------------------- the Python source parser

/// The Python type of a column, from the annotation and the `mapped_column`.
fn python_type(annotation: &str, args: &str) -> String {
    if let Some((_, digits)) = split_call(args, "String") {
        return format!("VARCHAR({digits})");
    }
    for (needle, ty) in [
        ("Text", "TEXT"),
        ("Float", "FLOAT"),
        ("Integer", "INTEGER"),
        ("Boolean", "BOOLEAN"),
        ("DateTime", "DATETIME"),
        ("JSON", "JSON"),
    ] {
        if contains_word(args, needle) {
            return ty.to_string();
        }
    }
    if contains_word(args, "ForeignKey") {
        return "INTEGER".to_string();
    }
    // No explicit type: it comes from the annotation.
    match annotation.trim() {
        "int" => "INTEGER".to_string(),
        "float" => "FLOAT".to_string(),
        "bool" => "BOOLEAN".to_string(),
        "str" => "VARCHAR".to_string(),
        "datetime" => "DATETIME".to_string(),
        "list" | "dict" => "JSON".to_string(),
        other => panic!("the Python type of `{other}` is not known"),
    }
}

/// Is `needle` a word in `haystack`?
fn contains_word(haystack: &str, needle: &str) -> bool {
    haystack
        .split(|c: char| !(c.is_alphanumeric() || c == '_'))
        .any(|word| word == needle)
}

/// The argument of a call, if it is there: `String(120)` gives `("String", "120")`.
fn split_call(args: &str, name: &str) -> Option<(String, String)> {
    let needle = format!("{name}(");
    let start = args.find(&needle)? + needle.len();
    let rest = &args[start..];
    let end = rest.find(')')?;
    Some((name.to_string(), rest[..end].to_string()))
}

/// The tables the Python models describe.
fn parse_python_models(path: &Path) -> Vec<Table> {
    let source = std::fs::read_to_string(path)
        .unwrap_or_else(|err| panic!("could not read {}: {err}", path.display()));
    let mut tables = Vec::new();

    // Split the file into class blocks.
    let mut blocks: Vec<(String, String)> = Vec::new();
    let mut current: Option<(String, String)> = None;
    for line in source.lines() {
        if line.starts_with("class ") {
            if let Some(block) = current.take() {
                blocks.push(block);
            }
            let name = line
                .trim_start_matches("class ")
                .split('(')
                .next()
                .unwrap_or_default()
                .to_string();
            current = Some((name, String::new()));
            continue;
        }
        if let Some(block) = current.as_mut() {
            block.1.push_str(line);
            block.1.push('\n');
        }
    }
    if let Some(block) = current.take() {
        blocks.push(block);
    }

    for (class_name, body) in blocks {
        if !body.contains("__tablename__") {
            continue;
        }
        tables.push(parse_python_table(&class_name, &body));
    }

    tables
}

/// One table, from one class body.
fn parse_python_table(class_name: &str, body: &str) -> Table {
    let name = body
        .split("__tablename__")
        .nth(1)
        .and_then(|rest| rest.split('"').nth(1))
        .unwrap_or_else(|| panic!("{class_name} has no __tablename__"))
        .to_string();

    let mut columns: Vec<Column> = Vec::new();
    let mut indexes: Vec<Index> = Vec::new();
    let mut unique_constraints: Vec<Vec<String>> = Vec::new();
    let mut foreign_keys: Vec<ForeignKey> = Vec::new();

    // The table arguments: UniqueConstraint and Index.
    if let Some(args) = table_args(body) {
        for (columns_of_constraint, _) in unique_constraints_in(&args) {
            unique_constraints.push(columns_of_constraint);
        }
        for (index_name, index_columns) in indexes_in(&args) {
            indexes.push(Index {
                name: index_name,
                unique: false,
                columns: index_columns,
            });
        }
    }

    // The columns.
    let lines: Vec<&str> = body.lines().collect();
    let mut index = 0;
    while index < lines.len() {
        let line = lines[index];
        let trimmed = line.trim();
        if !trimmed.contains(": Mapped[") || !trimmed.contains("mapped_column(") {
            index += 1;
            continue;
        }

        // Gather the statement, which may run over several lines.
        let mut statement = trimmed.to_string();
        while !balanced(&statement) && index + 1 < lines.len() {
            index += 1;
            statement.push(' ');
            statement.push_str(lines[index].trim());
        }

        let (field, annotation, args) = split_column(&statement);
        let ty = python_type(&annotation, &args);
        let optional = annotation.contains("| None");
        let explicit_nullable = if args.contains("nullable=True") {
            Some(true)
        } else if args.contains("nullable=False") {
            Some(false)
        } else {
            None
        };
        let notnull = match explicit_nullable {
            Some(value) => !value,
            None => !optional,
        };

        columns.push(Column {
            name: field.clone(),
            ty,
            notnull,
            // SQLAlchemy's `default=` is a Python-side default: it never
            // reaches the DDL.
            default: None,
            primary_key: args.contains("primary_key=True"),
        });

        if contains_word(&args, "ForeignKey") {
            foreign_keys.push(parse_foreign_key(&field, &args));
        }

        if args.contains("index=True") {
            let unique = args.contains("unique=True");
            indexes.push(Index {
                name: format!("ix_{name}_{field}"),
                unique,
                columns: vec![field.clone()],
            });
            if !unique && args.contains("unique=True") {
                unique_constraints.push(vec![field.clone()]);
            }
        } else if args.contains("unique=True") {
            unique_constraints.push(vec![field.clone()]);
        }

        index += 1;
    }

    Table {
        name,
        columns,
        unique_constraints,
        indexes,
        foreign_keys,
    }
}

/// The arguments of `__table_args__`.
fn table_args(body: &str) -> Option<String> {
    let start = body.find("__table_args__")?;
    let open = body[start..].find('(')? + start;
    let mut depth = 0;
    for (offset, character) in body[open..].char_indices() {
        match character {
            '(' => depth += 1,
            ')' => {
                depth -= 1;
                if depth == 0 {
                    return Some(body[open + 1..open + offset].to_string());
                }
            }
            _ => {}
        }
    }
    None
}

/// The `UniqueConstraint(...)` calls in the table arguments.
fn unique_constraints_in(args: &str) -> Vec<(Vec<String>, Option<String>)> {
    let mut out = Vec::new();
    let mut rest = args;
    while let Some(start) = rest.find("UniqueConstraint(") {
        let inner_start = start + "UniqueConstraint(".len();
        let inner = &rest[inner_start..];
        let end = inner.find(')').unwrap_or(inner.len());
        let inner = &inner[..end];
        let mut columns = Vec::new();
        let mut name = None;
        for part in split_arguments(inner) {
            let part = part.trim();
            if let Some(value) = part.strip_prefix("name=") {
                name = Some(value.trim_matches('"').to_string());
            } else if let Some(value) = part.strip_prefix('"') {
                columns.push(value.trim_end_matches('"').to_string());
            }
        }
        out.push((columns, name));
        rest = &rest[inner_start + end + 1..];
    }
    out
}

/// The `Index(...)` calls in the table arguments.
fn indexes_in(args: &str) -> Vec<(String, Vec<String>)> {
    let mut out = Vec::new();
    let mut rest = args;
    while let Some(start) = rest.find("Index(") {
        // `UniqueConstraint(` also ends in `Index(` — no it does not, but
        // `Index(` is a substring of `UniqueConstraint(`? No: "Constraint(" —
        // so it is safe.
        let inner_start = start + "Index(".len();
        let inner = &rest[inner_start..];
        let end = inner.find(')').unwrap_or(inner.len());
        let inner = &inner[..end];
        let parts = split_arguments(inner);
        let mut name = String::new();
        let mut columns = Vec::new();
        for (position, part) in parts.iter().enumerate() {
            let part = part.trim();
            if position == 0 {
                name = part.trim_matches('"').to_string();
            } else if let Some(value) = part.strip_prefix('"') {
                columns.push(value.trim_end_matches('"').to_string());
            }
        }
        out.push((name, columns));
        rest = &rest[inner_start + end + 1..];
    }
    out
}

/// Split `a, b, "c"` into its arguments, ignoring commas inside brackets.
fn split_arguments(text: &str) -> Vec<String> {
    let mut out = Vec::new();
    let mut current = String::new();
    let mut depth = 0;
    for character in text.chars() {
        match character {
            '(' | '[' => {
                depth += 1;
                current.push(character);
            }
            ')' | ']' => {
                depth -= 1;
                current.push(character);
            }
            ',' if depth == 0 => {
                out.push(current.trim().to_string());
                current = String::new();
            }
            _ => current.push(character),
        }
    }
    if !current.trim().is_empty() {
        out.push(current.trim().to_string());
    }
    out
}

/// The foreign key of a column.
fn parse_foreign_key(field: &str, args: &str) -> ForeignKey {
    let start = args.find("ForeignKey(").expect("no ForeignKey");
    let inner_start = start + "ForeignKey(".len();
    let inner = &args[inner_start..];
    let end = inner.find(')').unwrap_or(inner.len());
    let inner = &inner[..end];
    let parts = split_arguments(inner);

    let target = parts[0].trim().trim_matches('"').to_string();
    let (references_table, references_column) = match target.split_once('.') {
        Some((table, column)) => (table.to_string(), column.to_string()),
        None => (target.clone(), "id".to_string()),
    };
    let on_delete = parts
        .iter()
        .find_map(|part| part.strip_prefix("ondelete="))
        .map(|value| value.trim_matches('"').to_uppercase())
        .unwrap_or_else(|| "NO ACTION".to_string());

    ForeignKey {
        column: field.to_string(),
        references_table,
        references_column,
        on_delete,
    }
}

/// Are the parentheses balanced?
fn balanced(text: &str) -> bool {
    let mut depth = 0;
    for character in text.chars() {
        match character {
            '(' => depth += 1,
            ')' => depth -= 1,
            _ => {}
        }
    }
    depth <= 0
}

/// The field, the annotation and the arguments of a column statement.
fn split_column(statement: &str) -> (String, String, String) {
    let colon = statement.find(':').expect("no annotation");
    let field = statement[..colon].trim().to_string();
    let after = &statement[colon + 1..];
    let open = after.find('[').expect("no Mapped[]");
    let close = after.find(']').expect("no Mapped[] end");
    let annotation = after[open + 1..close].to_string();
    let args_start =
        after.find("mapped_column(").expect("no mapped_column") + "mapped_column(".len();
    let args = &after[args_start..];
    let args = args.strip_suffix(')').unwrap_or(args);
    (field, annotation, args.to_string())
}

// ------------------------------------------------------- the database itself

/// The schema the database actually has.
fn introspect(store: &Store) -> Vec<Table> {
    store
        .with_connection(|conn| {
            let mut names: Vec<String> = Vec::new();
            {
                let mut statement = conn
                    .prepare(
                        "SELECT name FROM sqlite_master WHERE type = 'table' \
                              AND name NOT LIKE 'sqlite_%' ORDER BY name",
                    )
                    .map_err(|source| StoreError::query("sqlite_master".to_string(), source))?;
                let rows = statement
                    .query_map([], |row| row.get::<_, String>(0))
                    .map_err(|source| StoreError::query("sqlite_master".to_string(), source))?;
                for row in rows {
                    names.push(row.map_err(|source| {
                        StoreError::query("sqlite_master".to_string(), source)
                    })?);
                }
            }

            let mut tables = Vec::new();
            for name in names {
                tables.push(introspect_table(conn, &name)?);
            }
            Ok(tables)
        })
        .expect("could not read the schema")
}

/// One table, as SQLite sees it.
fn introspect_table(conn: &rusqlite::Connection, name: &str) -> Result<Table, StoreError> {
    let mut columns: Vec<Column> = Vec::new();
    let mut primary_key: Vec<String> = Vec::new();
    {
        let mut statement = conn
            .prepare(&format!("PRAGMA table_info({name})"))
            .map_err(|source| StoreError::query(format!("table_info({name})"), source))?;
        let rows = statement
            .query_map([], |row| {
                Ok((
                    row.get::<_, String>(1)?,
                    row.get::<_, String>(2)?,
                    row.get::<_, i64>(3)?,
                    row.get::<_, Option<String>>(4)?,
                    row.get::<_, i64>(5)?,
                ))
            })
            .map_err(|source| StoreError::query(format!("table_info({name})"), source))?;
        for row in rows {
            let (column, ty, notnull, default, pk) =
                row.map_err(|source| StoreError::query(format!("table_info({name})"), source))?;
            if pk > 0 {
                primary_key.push(column.clone());
            }
            columns.push(Column {
                name: column,
                ty: ty.to_uppercase(),
                notnull: notnull != 0,
                default,
                primary_key: pk > 0,
            });
        }
    }

    let mut foreign_keys: Vec<ForeignKey> = Vec::new();
    {
        let mut statement = conn
            .prepare(&format!("PRAGMA foreign_key_list({name})"))
            .map_err(|source| StoreError::query(format!("foreign_key_list({name})"), source))?;
        let rows = statement
            .query_map([], |row| {
                Ok((
                    row.get::<_, String>(2)?,
                    row.get::<_, String>(3)?,
                    row.get::<_, Option<String>>(4)?,
                    row.get::<_, String>(6)?,
                ))
            })
            .map_err(|source| StoreError::query(format!("foreign_key_list({name})"), source))?;
        for row in rows {
            let (table, from, to, on_delete) = row
                .map_err(|source| StoreError::query(format!("foreign_key_list({name})"), source))?;
            foreign_keys.push(ForeignKey {
                column: from,
                references_table: table,
                references_column: to.unwrap_or_default(),
                on_delete: on_delete.to_uppercase(),
            });
        }
    }

    let mut indexes: Vec<Index> = Vec::new();
    let mut unique_constraints: Vec<Vec<String>> = Vec::new();
    {
        let mut statement = conn
            .prepare(&format!("PRAGMA index_list({name})"))
            .map_err(|source| StoreError::query(format!("index_list({name})"), source))?;
        let listed = statement
            .query_map([], |row| {
                Ok((
                    row.get::<_, String>(1)?,
                    row.get::<_, i64>(2)?,
                    row.get::<_, String>(3)?,
                ))
            })
            .map_err(|source| StoreError::query(format!("index_list({name})"), source))?;
        let mut list = Vec::new();
        for row in listed {
            list.push(
                row.map_err(|source| StoreError::query(format!("index_list({name})"), source))?,
            );
        }

        for (index_name, unique, origin) in list {
            let index_columns = index_columns(conn, name, &index_name)?;
            if origin == "c" {
                indexes.push(Index {
                    name: index_name,
                    unique: unique != 0,
                    columns: index_columns,
                });
            } else if origin == "u" {
                // A unique constraint, or the index SQLite made for the
                // primary key. The primary key one is not a constraint we
                // compare — the columns already say what the key is.
                let mut sorted = index_columns.clone();
                sorted.sort();
                let mut key = primary_key.clone();
                key.sort();
                if sorted != key {
                    unique_constraints.push(index_columns);
                }
            }
        }
    }

    Ok(Table {
        name: name.to_string(),
        columns,
        unique_constraints,
        indexes,
        foreign_keys,
    })
}

/// The columns of an index.
fn index_columns(
    conn: &rusqlite::Connection,
    table: &str,
    index: &str,
) -> Result<Vec<String>, StoreError> {
    let mut statement = conn
        .prepare(&format!("PRAGMA index_info({index})"))
        .map_err(|source| StoreError::query(format!("index_info({index})"), source))?;
    let rows = statement
        .query_map([], |row| row.get::<_, Option<String>>(2))
        .map_err(|source| StoreError::query(format!("index_info({index})"), source))?;
    let mut columns = Vec::new();
    for row in rows {
        let column =
            row.map_err(|source| StoreError::query(format!("index_info({index})"), source))?;
        if let Some(column) = column {
            columns.push(column);
        }
    }
    let _ = table;
    Ok(columns)
}

// --------------------------------------------------------------- comparison

/// Compare two sets of tables, and say what is different.
fn compare(expected: &[Table], actual: &[Table]) {
    let expected_by_name: BTreeMap<&str, &Table> = expected
        .iter()
        .map(|table| (table.name.as_str(), table))
        .collect();
    let actual_by_name: BTreeMap<&str, &Table> = actual
        .iter()
        .map(|table| (table.name.as_str(), table))
        .collect();

    let expected_names: Vec<&str> = expected_by_name.keys().copied().collect();
    let actual_names: Vec<&str> = actual_by_name.keys().copied().collect();
    assert_eq!(
        expected_names, actual_names,
        "the tables are not the same as the Python schema"
    );

    for (name, wanted) in &expected_by_name {
        let got = actual_by_name[name];
        assert_eq!(
            wanted.columns, got.columns,
            "the columns of `{name}` are not the Python columns"
        );
        assert_eq!(
            sorted_unique(&wanted.unique_constraints),
            sorted_unique(&got.unique_constraints),
            "the unique constraints of `{name}` are not the Python ones"
        );
        assert_eq!(
            sorted_indexes(&wanted.indexes),
            sorted_indexes(&got.indexes),
            "the indexes of `{name}` are not the Python ones"
        );
        assert_eq!(
            sorted_foreign_keys(&wanted.foreign_keys),
            sorted_foreign_keys(&got.foreign_keys),
            "the foreign keys of `{name}` are not the Python ones"
        );
    }
}

/// The unique constraints, sorted, so the order does not matter.
fn sorted_unique(constraints: &[Vec<String>]) -> Vec<Vec<String>> {
    let mut out: Vec<Vec<String>> = constraints
        .iter()
        .map(|columns| {
            let mut columns = columns.clone();
            columns.sort();
            columns
        })
        .collect();
    out.sort();
    out
}

/// The indexes, sorted by name.
fn sorted_indexes(indexes: &[Index]) -> Vec<Index> {
    let mut out = indexes.to_vec();
    out.sort();
    out
}

/// The foreign keys, sorted.
fn sorted_foreign_keys(keys: &[ForeignKey]) -> Vec<ForeignKey> {
    let mut out = keys.to_vec();
    out.sort();
    out
}

// ---------------------------------------------------------------- the tests

#[test]
fn the_schema_matches_the_python_models() {
    let root = repo_root();
    let mut expected = parse_python_models(&root.join("backend/app/models.py"));
    expected.extend(parse_python_models(
        &root.join("backend/app/models_phase2.py"),
    ));
    expected.sort();

    let dir = common::temp_dir("schema-python");
    let store =
        Store::open_and_migrate(&dir.join("stride.db"), &common::key()).expect("could not open");
    let actual = introspect(&store);

    compare(&expected, &actual);
}

#[test]
fn the_schema_matches_the_golden_sqlalchemy_snapshot() {
    let snapshot: serde_json::Value = serde_json::from_str(
        &std::fs::read_to_string(
            Path::new(env!("CARGO_MANIFEST_DIR")).join("tests/python_schema.json"),
        )
        .expect("could not read the snapshot"),
    )
    .expect("the snapshot is not JSON");

    let mut expected: Vec<Table> = Vec::new();
    let tables = snapshot
        .get("tables")
        .and_then(|value| value.as_object())
        .expect("the snapshot has no tables");
    for (name, table) in tables {
        let columns = table
            .get("columns")
            .and_then(|value| value.as_array())
            .expect("no columns")
            .iter()
            .map(|column| Column {
                name: column["name"].as_str().unwrap_or_default().to_string(),
                ty: column["type"].as_str().unwrap_or_default().to_uppercase(),
                notnull: column["notnull"].as_bool().unwrap_or(false),
                default: column["default"].as_str().map(str::to_string),
                primary_key: column["primary_key"].as_bool().unwrap_or(false),
            })
            .collect();
        let unique_constraints = table
            .get("unique_constraints")
            .and_then(|value| value.as_array())
            .map(|list| {
                list.iter()
                    .map(|columns| {
                        columns
                            .as_array()
                            .map(|columns| {
                                columns
                                    .iter()
                                    .map(|column| column.as_str().unwrap_or_default().to_string())
                                    .collect()
                            })
                            .unwrap_or_default()
                    })
                    .collect()
            })
            .unwrap_or_default();
        let indexes = table
            .get("indexes")
            .and_then(|value| value.as_array())
            .map(|list| {
                list.iter()
                    .map(|index| Index {
                        name: index["name"].as_str().unwrap_or_default().to_string(),
                        unique: index["unique"].as_bool().unwrap_or(false),
                        columns: index["columns"]
                            .as_array()
                            .map(|columns| {
                                columns
                                    .iter()
                                    .map(|column| column.as_str().unwrap_or_default().to_string())
                                    .collect()
                            })
                            .unwrap_or_default(),
                    })
                    .collect()
            })
            .unwrap_or_default();
        let foreign_keys = table
            .get("foreign_keys")
            .and_then(|value| value.as_array())
            .map(|list| {
                list.iter()
                    .map(|key| ForeignKey {
                        column: key["column"].as_str().unwrap_or_default().to_string(),
                        references_table: key["references_table"]
                            .as_str()
                            .unwrap_or_default()
                            .to_string(),
                        references_column: key["references_column"]
                            .as_str()
                            .unwrap_or_default()
                            .to_string(),
                        on_delete: key["on_delete"].as_str().unwrap_or_default().to_uppercase(),
                    })
                    .collect()
            })
            .unwrap_or_default();

        expected.push(Table {
            name: name.clone(),
            columns,
            unique_constraints,
            indexes,
            foreign_keys,
        });
    }
    expected.sort();

    let dir = common::temp_dir("schema-snapshot");
    let store =
        Store::open_and_migrate(&dir.join("stride.db"), &common::key()).expect("could not open");
    let actual = introspect(&store);

    compare(&expected, &actual);
}
